def apply_split_payment(balance_cents: int, part_a_cents: int, part_b_cents: int) -> int:
    if not all(isinstance(x, int) for x in (balance_cents, part_a_cents, part_b_cents)):
        raise TypeError('All monetary amounts must be integer cents')
    if part_a_cents + part_b_cents > balance_cents:
        raise ValueError('Insufficient funds')
    return balance_cents - (part_a_cents + part_b_cents)

